/**
 * Barrel for the aspect wire-shape mirrors. Top-level aspect shapes
 * (inputs, read responses, pull responses, write responses) live in
 * `aspect.ts`. Per-variant field shapes and format/picklist sub-shapes
 * stay split out:
 *   - `aspect.ts`           — every top-level aspect wire shape:
 *                             `AspectDefinitionInput`, `AspectPullInput`,
 *                             `AgentAspectInput`, `AgentAspectUpdateInput`,
 *                             `AgentFieldUpdateInput`, supporting input
 *                             sub-shapes (category, cloud, service,
 *                             record-create), read shapes (`Aspect`,
 *                             `AspectField`, `PicklistValue`,
 *                             search tables), pull-side extensions
 *                             (`AspectPullResponse`,
 *                             `AspectFieldPullResponse`,
 *                             `AspectPicklistDynamicConfigRef`), and
 *                             compose/update response shapes
 *                             (`AspectFieldResult`,
 *                             `AspectOperationSummary`,
 *                             `ComposeAspectWireResponse`,
 *                             `UpdateAspectWireResponse`,
 *                             `DeployedAspect`).
 *   - `field-base.ts`       — `AspectFieldBaseInput` (shared base for
 *                             compose-side field inputs).
 *   - `field-types.ts`      — 14 per-variant compose-side field inputs
 *                             + `AspectFieldInput` discriminated union.
 *   - `format.ts`           — bidirectional format shapes (numeric /
 *                             qr / reference) — one type per kind
 *                             serves both compose inputs and pull
 *                             responses; plus currency code.
 *   - `picklist-config.ts`  — input-side picklist config (`PicklistConfigInput`
 *                             + static/dynamic sub-shapes,
 *                             `PicklistValueExInput`).
 */
export {};
